/**
 * Post codes (Beitragscode, decision D5 of PORTAL-ORGANISCH-BAUPLAN.md):
 * generated by the portal, 5 characters, opaque by construction.
 *
 * Alphabet: consonants without vowels and without "y" and "l", digits without
 * 0 and 1, so a code can never spell a word (and never a treatment) and is
 * unambiguous when read aloud or typed. Every code has at least one letter
 * and at least one digit, which also keeps it apart from ad names in
 * utm_content. The pattern is the ONLY test of "is this a post code": a value
 * that does not match is never treated as one (intake, clinic-landing URL
 * rule D6).
 *
 * The same pattern lives in apps/clinic-landing/lib/post-code.ts; the test
 * in both apps pins it to POST_CODE_PATTERN_SOURCE.
 */

export const POST_CODE_LETTERS = "bcdfghjkmnpqrstvwxz";
export const POST_CODE_DIGITS = "23456789";
export const POST_CODE_LENGTH = 5;

export const POST_CODE_PATTERN_SOURCE =
  "^(?=[bcdfghjkmnpqrstvwxz2-9]*[2-9])(?=[bcdfghjkmnpqrstvwxz2-9]*[bcdfghjkmnpqrstvwxz])[bcdfghjkmnpqrstvwxz2-9]{5}$";
const POST_CODE_PATTERN = new RegExp(POST_CODE_PATTERN_SOURCE);

export function isPostCode(value: unknown): value is string {
  return typeof value === "string" && POST_CODE_PATTERN.test(value);
}

/** utm_content as a post code, or null (ad names, free text, anything else). */
export function postCodeFromUtm(utm: unknown): string | null {
  if (!utm || typeof utm !== "object" || Array.isArray(utm)) return null;
  const v = (utm as Record<string, unknown>).utm_content;
  const s = typeof v === "string" ? v.trim().toLowerCase() : null;
  return isPostCode(s) ? s : null;
}

/** Uniform integer in [0, max) from Web Crypto (works in Node and the browser). */
function cryptoInt(max: number): number {
  const limit = Math.floor(0x1_0000_0000 / max) * max;
  const buf = new Uint32Array(1);
  for (;;) {
    globalThis.crypto.getRandomValues(buf);
    if (buf[0]! < limit) return buf[0]! % max;
  }
}

/** A fresh random post code. Uniqueness per Praxis is the caller's job (unique index, retry). */
export function generatePostCode(rand: (max: number) => number = cryptoInt): string {
  const all = POST_CODE_LETTERS + POST_CODE_DIGITS;
  for (;;) {
    let code = "";
    for (let i = 0; i < POST_CODE_LENGTH; i++) code += all[rand(all.length)];
    if (isPostCode(code)) return code;
  }
}
